 let ns=isoNs(d.utc_estimated),check=value=>{let delta=ns-value;if(delta<0n)delta=-delta;if(delta>1000n){let error=Error('UTC 文字、epoch 或當地時間不一致；請回原工具確認日期／時區後重新匯出');error.fatal=true;throw error}};
