function csvCell(v){let s=v===null||v===undefined?'':String(v);if(/^[=+@\-]/.test(s)&&typeof v!=='number')s="'"+s;return /[",\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
